const clean=s=>s.replace(/[.!?]+$/,"").replace(/\b(?:i\.e|e\.g)\./g,"").trim();
const words=s=>s.trim().split(/\s+/).filter(Boolean);
const dimsLabel={logicalCoherence:"logical coherence",evidenceWarrant:"evidential warrant",responsiveness:"responsiveness",relevanceBurden:"burden relevance",precisionClarity:"precision and clarity",calibrationCharity:"calibration and charity"};
const styles=[
["Its carefully bounded inference connects","The unresolved vulnerability is","Further evaluation therefore requires","This result belongs in the strong band because"],
["The move advances the exchange by showing","Its principal evidential weakness remains","The surviving comparative question is","The frozen number is proportionate because"],
["Most persuasive is the explicit distinction between","What prevents a higher rating is","To complete the argumentative bridge, the speaker must","The assigned result reflects"],
["The source-grounded comparison makes credible","The argument nevertheless underdevelops","The live burden now becomes whether","The locked assessment appropriately recognizes"],
["The response directly isolates","Its limiting feature is the absence of","A decisive continuation would need to establish","The score preserves credit for"],
["The central achievement is demonstrating","The passage remains materially incomplete because","The unanswered burden concerns","The numerical judgment balances"],
["The reasoning gains force from","The remaining defect arises where","What still needs demonstration is","The settled score rewards"],
["The move usefully clarifies","Its most consequential limitation concerns","The debate therefore leaves open whether","The final mark distinguishes"]
