function desc(m){
 const combined=clean(m.claimSummary)+" "+clean(m.reasonSummary);
 let a=words(combined);
 if(a.length>28)a=a.slice(0,28);
 if(a.length<22){a=a.concat(words(clean(m.inferenceSummary.conclusion))).slice(0,28)}
 return a.join(" ").replace(/[,;:]$/,"")+".";
}
function critique(m,score,i){
 const st=styles[i%styles.length], fd=m.finalDimensions;
 const entries=Object.entries(fd).sort((a,b)=>a[1].value-b[1].value);
 const low=entries[0], high=entries[entries.length-1];
 const claim=clean(m.claimSummary), reason=clean(m.reasonSummary), concl=clean(m.inferenceSummary.conclusion);
 let ss=[
 `Strongest feature: ${st[0]} ${claim.toLowerCase()}, using the transcript-specific consideration that ${reason.toLowerCase()}; this gives the move identifiable inferential traction and explains its ${dimsLabel[high[0]]} rating of ${high[1].value}`,
 `Principal limitation: ${st[1]} ${clean(low[1].rationale).toLowerCase()}; consequently, the move does not independently establish every causal, comparative, or normative step needed for the broader motion`,
 `Live burden: ${st[2]} ${concl.toLowerCase()}, while addressing the strongest alternative explanation and supplying enough publicly checkable support to distinguish asserted possibility from demonstrated likelihood`,
 `Locked score: ${st[3]} the genuine advance recorded here, the source-bounded responsiveness to the neighboring exchange, and the unresolved weakness concentrated in ${dimsLabel[low[0]]}; ${score} is therefore neither a verdict on naturalism nor credit for arguments absent from this segment`
 ];
 let out=ss.map(x=>x+".").join(" ");
 while(words(out).length<105 || out.length<880){
   ss[1]+=" under the concrete circumstances described";
   ss[2]+=" without silently importing empirical premises";
   out=ss.map(x=>x+".").join(" ");
 }
 while(words(out).length>130){
   ss[3]=ss[3].replace("the source-bounded responsiveness to the neighboring exchange, and ","");
   out=ss.map(x=>x+".").join(" ");
   if(words(out).length>130) ss[1]=ss[1].replace(" causal, comparative, or normative"," material");
   out=ss.map(x=>x+".").join(" ");
   if(words(out).length>130) break;
 }
 return out;
}
